  if(!elevated&&['wall','door','fence','bench','post','firebowl','chest','wardrobe','bed','campfire'].includes(b.kind)&&Math.hypot(b.x-s.x,b.z-s.z)<.95){plan.ok=false;plan.reason='Allontanati dal pezzo'}
