function nearStructure(){if(insideInstance)return null;return s.buildings.filter(b=>['door','bench','chest','wardrobe','bed'].includes(b.kind)&&Math.hypot(s.x-b.x,s.z-b.z)<2.6).sort((a,b)=>Math.hypot(s.x-a.x,s.z-a.z)-Math.hypot(s.x-b.x,s.z-b.z))[0]}
function structureUse(b){if(b.kind==='bed'){if(!sleepAt(s,b.id)){toast('Puoi dormire dalle 20:00 alle 08:00.');return}toast('Hai riposato fino alle 08:00 · punto di rinascita salvato.');updateHud();save();return}if(['chest','wardrobe'].includes(b.kind)){useChest(builtChest(b));return}if(b.kind==='bench'){openBag('bench');return}b.open=!b.open;const m=built.get(b.id);if(m?.hinge)m.hinge.rotation.y=b.open?Math.PI/2:0;save();toast(b.open?'Porta aperta':'Porta chiusa')}
