function clearGround(){for(const m of groundMeshes.values())scene.remove(m);groundMeshes.clear();for(const m of graveMeshes.values())scene.remove(m);graveMeshes.clear()}
const graveMeshes=new Map();
function graveNear(){return s.graves.find(g=>g.area===currentArea()&&Math.hypot(g.x-s.x,g.z-s.z)<=2.5)}
