function animateChests(dt){const turn=(lid,id)=>{if(lid)lid.rotation.x+=((activeChest?.id===id?-1.9:0)-lid.rotation.x)*smoothFactor(9,dt)};for(const r of loot)turn(r.lid,r.id);for(const [id,m] of built){turn(m.lid,'built:'+id);for(const d of m.doors||[])d.g.rotation.y+=((activeChest?.id==='built:'+id?d.sign*1.55:0)-d.g.rotation.y)*smoothFactor(9,dt)}}
