 function wire(b,source,item,index,qty){b.dataset.source=source;b.dataset.item=item||'';b.dataset.index=index??'';b.draggable=!!item;b.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',JSON.stringify({source,item,index,qty}));e.dataTransfer.effectAllowed='move'});b.addEventListener('dblclick',()=>item&&transfer(source,item,index,qty));b.addEventListener('contextmenu',e=>{e.preventDefault();if(item)transfer(source,item,index,1)});b.addEventListener('click',()=>select(source,item,index))}
