function witchTrade(){if(s.opened['witch-remedy']){toast('La strega: che gli antenati ti proteggano.');return}if(!has(s,{mushroom:3,reed:4})){toast('La strega: portami 3 funghi e 4 giunchi.');return}take(s,'mushroom',3);take(s,'reed',4);add(s,'food',3);add(s,'venom',2);s.health=100;s.opened['witch-remedy']=true;toast('Rimedio della strega: salute ripristinata, cibo ed essenza.');updateHud();save()}
